def commit(state, batch):
    balances = dict(state['balances'])
    seen = {k: list(v) for k, v in state['seen'].items()}
    for event in batch:
        if not isinstance(event, (list, tuple)) or len(event) != 4:
            raise ValueError("invalid")
        event_id, src, dst, amount = event
        if not isinstance(event_id, str):
            raise ValueError("invalid")
        if not isinstance(src, str) or not isinstance(dst, str):
            raise ValueError("invalid")
        if src == dst:
            raise ValueError("invalid")
        if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
            raise ValueError("invalid")
        if src not in balances or dst not in balances:
            raise ValueError("invalid")
        if event_id in seen:
            if seen[event_id] == [src, dst, amount]:
                continue
            raise ValueError("conflict")
        if balances[src] < amount:
            raise ValueError("funds")
        balances[src] -= amount
        balances[dst] += amount
        seen[event_id] = [src, dst, amount]
    return {'balances': balances, 'seen': seen}

